rules.bad:
@Test void test1_createUser() { ... }
@Test void test2_updateUser() { /* 依赖 test1 创建的数据 */ }
// 或共享 static 可变字段跨用例传递状态

rules.good:
每个 @Test 方法内部自行准备数据（@BeforeEach），用例之间无共享可变状态；
@BeforeEach void setUp() { user = userRepository.save(newUser()); }
// 需要清理的用 @AfterEach，或使用事务回滚

rules.bad:
@Test void testCalc() {
  System.out.println(calc(1, 2));   // 靠眼睛看
}

rules.good:
@Test void testCalc() {
  assertEquals(3, calc(1, 2));
  assertThrows(BizException.class, () -> calc(null, 2));
}

rules.bad:
@Test void testQuery() {
  // 直连测试库真实查询，依赖库里有特定数据
  assertEquals("mryang", dao.selectById(1).getName());
}

rules.good:
@ExtendWith(MockitoExtension.class)
class UserServiceTest {
  @Mock UserDao userDao;
  @InjectMocks UserService userService;

  @Test void testQuery() {
    when(userDao.selectById(1L)).thenReturn(new User("mryang"));
    assertEquals("mryang", userService.get(1L).getName());
  }
}
